-- Native German copy; stable IDs retain each couple's question history.
with scenes as (
 select category, scene, n-1 as i from jsonb_each('{"Us":["Wir haben zusammen etwas geschafft, das uns wichtig ist.","Zu unserem Alltag gehören kleine Rituale.","Wir müssen eine Entscheidung treffen, die uns beide betrifft.","Wir lachen manchmal über Dinge, die sonst niemand lustig findet.","Wir teilen uns ein Zuhause oder stellen uns das vor.","Eine kleine Geste kann zeigen, dass wir einander schätzen.","Wir probieren zusammen etwas aus, das wir noch nicht kennen.","Im Alltag bleibt manchmal wenig Zeit für uns.","Wir zeigen unsere Zuneigung auf unterschiedliche Weise.","Wir stehen vor einer Aufgabe, die wir nur gemeinsam lösen können.","Wir sind uns in manchen Dingen ähnlich und in anderen sehr verschieden.","Auch in einer Beziehung braucht jeder Zeit für sich."],"Future":["Stell dir das Zuhause vor, in dem wir uns beide wohlfühlen würden.","Stell dir eine Reise vor, die wir schon lange machen möchten.","Stell dir vor, wir blicken fünf Jahre in die Zukunft.","Stell dir vor, wir sind gemeinsam alt geworden.","Stell dir vor, wir lernen zusammen eine neue Fähigkeit.","Stell dir eine neue Tradition vor, die nur uns beiden gehört.","Stell dir ein gemeinsames Projekt vor, auf das wir stolz sein könnten.","Stell dir vor, wir könnten unseren Wohnort frei wählen.","Stell dir vor, unsere Wochenenden wären ganz nach unseren Wünschen gestaltet.","Stell dir vor, einer unserer gemeinsamen Träume wird wahr.","Stell dir eine größere Entscheidung vor, die als Nächstes auf uns zukommen könnte.","Stell dir vor, wir könnten unseren Alltag deutlich ruhiger gestalten."],"Dreams":["Denk an etwas Kreatives, das du gern verwirklichen würdest.","Denk an ein Abenteuer, von dem du schon länger träumst.","Denk an eine Eigenschaft, die du gern in dir stärken möchtest.","Denk an einen Ort, den du unbedingt kennenlernen möchtest.","Denk an eine Fähigkeit, die du gern richtig gut beherrschen würdest.","Denk daran, was für dich ein erfülltes Leben ausmacht.","Denk an etwas, das du nur aus Freude erschaffen würdest.","Denk an einen Wunsch, den du als Teenager hattest.","Denk an eine Chance, die du gern einmal ergreifen würdest.","Denk daran, wie ein Leben mit mehr Freiheit für dich aussehen könnte.","Denk an ein Projekt, das du am liebsten gleich beginnen würdest.","Denk an einen Wunsch, von dem bisher nur wenige Menschen wissen."],"Childhood":["Erinnere dich an die Spiele, die du als Kind geliebt hast.","Erinnere dich an die Gegend, in der du aufgewachsen bist.","Erinnere dich an eine deiner ersten Freundschaften.","Erinnere dich an ein Ritual aus deiner Familie.","Erinnere dich an Geschichten, die dir als Kind erzählt wurden.","Erinnere dich an einen Moment, in dem du erstmals etwas allein geschafft hast.","Erinnere dich an einen Erwachsenen, zu dem du aufgeschaut hast.","Erinnere dich an einen Ort, den du als Kind gern erkundet hast.","Erinnere dich an die Fantasiewelten, die du dir als Kind ausgedacht hast.","Erinnere dich an einen typischen Schultag.","Erinnere dich an Dinge, die du als Kind gesammelt hast.","Erinnere dich an etwas, das du schon früh fürs Leben gelernt hast."],"Memories":["Denk an eines unserer ersten gemeinsamen Abenteuer.","Denk an einen Moment, in dem wir kaum aufhören konnten zu lachen.","Denk an einen Ort, der dich an uns erinnert.","Denk an ein gemeinsames Essen, das dir besonders in Erinnerung geblieben ist.","Denk an eine Überraschung, über die du dich sehr gefreut hast.","Denk an einen schwierigen Tag, den wir zusammen gemeistert haben.","Denk an ein Lied, mit dem du eine bestimmte Erinnerung verbindest.","Denk an eine Reise, die dich geprägt hat.","Denk an einen Moment, in dem jemand unerwartet freundlich zu dir war.","Denk an eine Feier, die dir viel bedeutet hat.","Denk an ein Foto, das du besonders gern anschaust.","Denk an einen unspektakulären Tag, den du trotzdem nicht vergessen hast."],"Funny":["Wir gründen zusammen eine völlig absurde Firma.","Wir treten gemeinsam bei einer Talentshow auf.","Wir fahren spontan in den Urlaub und vergessen das gesamte Gepäck.","Unser Alltag wird eine Realityshow.","Ein etwas überforderter Roboter kocht unser Abendessen.","Unsere Haustiere oder die Tiere im Park können plötzlich sprechen.","Wir werden zu Superhelden mit ziemlich unnützen Kräften.","Wir ziehen in das unpraktischste Haus der Welt.","Wir müssen ohne Vorbereitung gemeinsam auf eine Comedy-Bühne.","Wir nehmen an einem Wettbewerb teil, für den wir völlig ungeeignet sind.","Wir werden für einen Tag zum Königspaar ernannt.","Wir erfinden ein Gerät, das ein völlig unnötiges Problem löst."],"Vulnerable":["Manchmal fällt es schwer, um Unterstützung zu bitten.","Manchmal wünscht man sich, wirklich verstanden zu werden.","Eigene Bedürfnisse auszusprechen ist nicht immer leicht.","Jeder von uns macht Fehler.","Es ist nicht immer einfach, dem eigenen Urteil zu vertrauen.","Manchmal entsteht der Druck, schon alles im Leben im Griff haben zu müssen.","In einer Beziehung möchten wir uns sicher fühlen.","Eigene Grenzen zu setzen kann Überwindung kosten.","Es braucht Vertrauen, eine Sorge offen anzusprechen.","Manchmal muss man sich selbst erlauben, eine Pause zu machen.","Ein ehrliches Kompliment anzunehmen kann überraschend schwer sein.","Die eigene verletzliche Seite zu zeigen braucht Mut."],"Random":["Denk an ein Lied, das deine Stimmung sofort verändert.","Denk an einen Ort, an dem du dich zu Hause fühlst.","Denk an eine Gewohnheit, die du gern ausprobieren würdest.","Denk an ein Buch, das dir in Erinnerung geblieben ist.","Denk an einen kleinen Luxus, den du dir im Alltag gönnst.","Denk an ein Gespräch, das du gern einmal führen würdest.","Denk an etwas Ungewöhnliches, das du schön findest.","Denk an eine Fähigkeit, die du an anderen bewunderst.","Denk an eine Frage, die dir viel zu selten gestellt wird.","Denk an ein Geräusch, das du besonders gern hörst.","Denk an einen gut gemeinten Rat, den du nicht überzeugend findest.","Denk an einen Tag, der unerwartet schön geworden ist."]}'::jsonb) c(category,items)
 cross join lateral jsonb_array_elements_text(items) with ordinality a(scene,n)
), followups as (
 select category, question, n-1 as j from jsonb_each('{"Us":["Was gefällt dir daran bei uns besonders?","Was würdest du dir dabei öfter von mir wünschen?","Welche kleine Veränderung würde uns guttun?","Wann hat sich das für dich zuletzt besonders schön angefühlt?","Was sollten wir dabei unbedingt beibehalten?","Was erlebst du dabei anders als ich?","Woran merkst du dabei, dass wir ein gutes Team sind?","Was könnten wir dazu diese Woche gemeinsam ausprobieren?"],"Future":["Wie sieht das in deiner Vorstellung ganz konkret aus?","Was wäre dir dabei am wichtigsten?","Welchen ersten kleinen Schritt könnten wir dafür machen?","Was müssten wir vorher miteinander besprechen?","Was macht dir an dieser Vorstellung Freude?","Welche Unsicherheit würdest du gern mit mir teilen?","Was wäre dabei ein guter Kompromiss für uns beide?","Was möchtest du dabei auf keinen Fall aus den Augen verlieren?"],"Dreams":["Was bedeutet dir dieser Wunsch persönlich?","Wie ist dieser Wunsch entstanden?","Was wäre ein kleiner Schritt in diese Richtung?","Wie könnte ich dich dabei unterstützen?","Was würdest du dafür gern lernen oder ausprobieren?","Was hält dich bisher davon ab?","Wie würde es sich anfühlen, diesem Wunsch näherzukommen?","Woran würdest du merken, dass du auf einem guten Weg bist?"],"Childhood":["Welche Szene fällt dir dazu als Erstes ein?","Mit wem verbindest du diese Erinnerung?","Was hat dir damals besonders viel bedeutet?","Was würdest du mir darüber gern erzählen?","Wie fühlt sich diese Erinnerung heute an?","Was sehe ich vielleicht anders, wenn ich diese Geschichte kenne?","Was war für dein jüngeres Ich damals ganz selbstverständlich?","Welche kleine Einzelheit ist dir bis heute geblieben?"],"Memories":["Was macht diese Erinnerung für dich besonders?","Welches Detail siehst du noch genau vor dir?","Welches Gefühl kommt dabei wieder hoch?","Was würdest du mir darüber gern erzählen?","Was würdest du gern von diesem Moment bewahren?","Was ist dir damals durch den Kopf gegangen?","Wie würdest du diesen Moment jemandem beschreiben, der nicht dabei war?","Hat sich dein Blick auf diese Erinnerung mit der Zeit verändert?"],"Funny":["Was wäre dein erster Satz in dieser Situation?","Welche Rolle würde jeder von uns übernehmen?","Was würde dabei garantiert schiefgehen?","Wie würden wir uns aus der peinlichsten Situation retten?","Wer von uns müsste zuerst lachen, und warum?","Welchen völlig übertriebenen Namen würden wir dem Ganzen geben?","Welche Szene würde auf jeden Fall in unserem Erinnerungsalbum landen?","Wie würde das Ganze in einem überraschend guten Ende ausgehen?"],"Vulnerable":["Wie geht es dir persönlich damit?","Was hilft dir in solchen Momenten?","Was möchtest du, dass ich darüber weiß?","Wie kann ich dir dabei Rückhalt geben?","Was sollte ich dabei lieber nicht tun?","Wann fällt dir das leichter als sonst?","Was hast du darüber im Laufe der Zeit gelernt?","Welcher kleine Schritt würde sich für dich gut und sicher anfühlen?"],"Random":["Was spricht dich daran besonders an?","Welche Geschichte verbindest du damit?","Was würdest du mir darüber gern erzählen?","Was sagt das vielleicht über dich aus?","Wann hast du zuletzt daran gedacht?","Wie würdest du mir erklären, was dir daran wichtig ist?","Was überrascht andere daran vielleicht?","Hat sich deine Sicht darauf mit der Zeit verändert?"]}'::jsonb) c(category,items)
 cross join lateral jsonb_array_elements_text(items) with ordinality a(question,n)
)
update public.game_content c set prompt=s.scene||' '||f.question
from scenes s join followups f using(category)
where c.id='fresh-talk-'||lower(s.category)||'-'||s.i||'-'||f.j;
update public.game_content c set prompt=q.value
